def minimize_path_weights(n: int, edges: List[Tuple[int, int, int]], a: List[int], b: List[int]) -> int:
    # Create an initial empty dp table
    dp = [[float("inf")] * (1 << n) for _ in range(n)]

    # Set the initial values for the first and last vertices
    dp[0][a[0] << n | b[0]] = 0
    dp[n-1][a[n-1] << n | b[n-1]] = 0

    # Build the dp table
    for i in range(1, n):
        for u in range(n):
            for v in range(n):
                for mask_u in range(1 << n):
                    for mask_v in range(1 << n):
                        # Update dp[u][mask_u] if the path from u to v has a lower weight
                        if edges[u][2] < edges[v][2]:
                            dp[u][mask_u] = min(dp[u][mask_u], dp[v][mask_v | (u << i)] + edges[u][2])
                        elif u << i | mask_u > mask_v:
                            dp[u][mask_u] = min(dp[u][mask_u], dp[v][mask_v | (u << i)] + edges[v][2])

    return dp[n-1][a[n-1] << n]
